// Transform Aviaframe format to DRCT API format
const body = $input.item.json.body || $input.item.json;

if (!body || typeof body !== 'object') {
  throw new Error('Request body is required');
}

const normalized = {
  origin: body.origin,
  destination: body.destination,
  depart_date: body.depart_date || body.departureDate,
  return_date: body.return_date || body.returnDate,
  adults: body.adults,
  children: body.children,
  infants: body.infants,
  cabin_class: body.cabin_class || body.cabinClass,
};

// Validate required fields
if (!normalized.origin || !normalized.destination || !normalized.depart_date) {
  throw new Error('origin, destination, and depart_date are required');
}

// Ensure date format is YYYY-MM-DD
function formatDate(dateStr) {
  if (!dateStr) return null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
    return dateStr;
  }
  const date = new Date(dateStr);
  if (isNaN(date.getTime())) {
    throw new Error(`Invalid date format: ${dateStr}`);
  }
  return date.toISOString().split('T')[0];
}

const originCode = String(normalized.origin).trim().toUpperCase();
const destinationCode = String(normalized.destination).trim().toUpperCase();

// Build flights array
const flights = [];

flights.push({
  departure_airport_code: originCode,
  arrival_airport_code: destinationCode,
  departure_date: formatDate(normalized.depart_date)
});

if (normalized.return_date) {
  flights.push({
    departure_airport_code: destinationCode,
    arrival_airport_code: originCode,
    departure_date: formatDate(normalized.return_date)
  });
}

// Build passengers array
const passengers = [];
const adults = Number(normalized.adults || 1);
for (let i = 0; i < adults; i++) {
  passengers.push({ type: "ADT" });
}

const children = Number(normalized.children || 0);
for (let i = 0; i < children; i++) {
  passengers.push({ type: "CHD" });
}

const infants = Number(normalized.infants || 0);
for (let i = 0; i < infants; i++) {
  passengers.push({ type: "INF" });
}

const drctRequest = {
  flights,
  passengers,
};

if (normalized.cabin_class) {
  drctRequest.filters = {
    cabin_class: String(normalized.cabin_class).toLowerCase()
  };
}

console.log('[Transform] Converted to DRCT format:', JSON.stringify(drctRequest, null, 2));

return drctRequest;

// Transform DRCT API response to Aviaframe format
let data = $input.item.json;

if (Array.isArray(data) && data.length > 0) {
  data = data[0];
}

console.log('[Transform] Data keys:', Object.keys(data || {}));

if (data?.error) {
  return {
    search_id: data.id || 'unknown',
    offers: [],
    error: {
      code: data.error.code || 'DRCT_API_ERROR',
      message: data.error.message || 'Failed to fetch search results from DRCT API'
    }
  };
}

const segments = Array.isArray(data?.segments) ? data.segments : [];
const fares = Array.isArray(data?.fares) ? data.fares : [];
const legacyOffers = Array.isArray(data?.offers) ? data.offers : [];
const flightOptions = Array.isArray(data?.flights_options) ? data.flights_options : [];

const segmentMap = {};
segments.forEach((segment) => {
  if (segment?.id) {
    segmentMap[segment.id] = segment;
  }
});

const fareMap = {};
fares.forEach((fare) => {
  if (fare?.id) {
    fareMap[fare.id] = fare;
  }
});

const toSegmentVm = (segment) => ({
  origin: segment?.departure_airport?.code || null,
  destination: segment?.arrival_airport?.code || null,
  departure: segment?.departure_date && segment?.departure_time
    ? `${segment.departure_date} ${segment.departure_time}`
    : null,
  arrival: segment?.arrival_date && segment?.arrival_time
    ? `${segment.arrival_date} ${segment.arrival_time}`
    : null,
  carrier: segment?.carrier?.airline_code || null,
  flight_number: segment?.flight_number || null,
  aircraft: segment?.aircraft || null,
  duration: Number(segment?.duration || 0)
});

const buildOfferVm = ({ offer, fare, flightSegments, fallbackId }) => {
  const firstSegment = flightSegments[0] || {};
  const lastSegment = flightSegments[flightSegments.length - 1] || {};
  const airlineCode = firstSegment?.carrier?.airline_code || 'N/A';
  const airlineName = firstSegment?.carrier?.airline_name || airlineCode;
  const baggage = Array.isArray(fare?.baggage) ? fare.baggage : [];

  return {
    offer_id: offer?.id || fallbackId,
    origin: firstSegment?.departure_airport?.code || 'N/A',
    destination: lastSegment?.arrival_airport?.code || 'N/A',
    departure_time: firstSegment?.departure_date && firstSegment?.departure_time
      ? `${firstSegment.departure_date} ${firstSegment.departure_time}`
      : 'N/A',
    arrival_time: lastSegment?.arrival_date && lastSegment?.arrival_time
      ? `${lastSegment.arrival_date} ${lastSegment.arrival_time}`
      : 'N/A',
    airline_code: airlineCode,
    airline_name: airlineName,
    flight_number: firstSegment?.flight_number || 'N/A',
    price: {
      total: Number(offer?.price?.amount || offer?.price?.total || 0),
      currency: offer?.price?.currency || 'USD',
      base: Number(offer?.price_details?.[0]?.fare?.amount || offer?.price_details?.[0]?.price?.fare?.amount || 0),
      taxes: Number(offer?.price_details?.[0]?.taxes?.amount || offer?.price_details?.[0]?.price?.taxes?.amount || 0)
    },
    duration: flightSegments.reduce((sum, segment) => sum + Number(segment?.duration || 0), 0),
    stops: Math.max(0, flightSegments.length - 1),
    cabin_class: fare?.cabin_class || 'Economy',
    baggage,
    fare_details: fare || null,
    segments: flightSegments.map(toSegmentVm)
  };
};

let transformedOffers = [];

if (flightOptions.length > 0) {
  transformedOffers = flightOptions.flatMap((option, optionIndex) => {
    const optionFlights = Array.isArray(option?.flights) ? option.flights : [];
    const segmentIds = optionFlights.flatMap((flight) => Array.isArray(flight?.segments) ? flight.segments : []);
    const flightSegments = segmentIds.map((id) => segmentMap[id]).filter(Boolean);

    return (Array.isArray(option?.offers) ? option.offers : []).map((offer, offerIndex) => {
      const fareRef = Array.isArray(offer?.fares) ? offer.fares[0] : null;
      const fare = fareRef?.id ? fareMap[fareRef.id] || fareRef : fareRef;
      return buildOfferVm({
        offer,
        fare,
        flightSegments,
        fallbackId: `offer-${optionIndex}-${offerIndex}`
      });
    });
  });
} else {
  transformedOffers = legacyOffers.map((offer, index) => {
    const fareRef = Array.isArray(offer?.fares) ? offer.fares[0] : null;
    const fare = fareRef?.id ? fareMap[fareRef.id] || fareRef : fareRef;
    const segmentIds = Array.isArray(fareRef?.segments)
      ? fareRef.segments
      : Array.isArray(fare?.segments)
        ? fare.segments
        : [];
    const flightSegments = segmentIds.map((id) => segmentMap[id]).filter(Boolean);
    return buildOfferVm({
      offer,
      fare,
      flightSegments,
      fallbackId: `offer-${index}`
    });
  });
}

console.log(`[Transform] Created ${transformedOffers.length} offers`);
if (transformedOffers.length > 0) {
  console.log('[Transform] Sample offer:', JSON.stringify(transformedOffers[0], null, 2));
}

return {
  search_id: data?.id || `search-${Date.now()}`,
  offers: transformedOffers
};

